# apply 3x3 around 2 if adjacent to any 3 (including center) and retain 2
B=A.copy()
for r,c in np.argwhere(A==2):
 if any(0<=r+dr<16 and 0<=c+dc<27 and A[r+dr,c+dc]==3 for dr in [-1,0,1] for dc in [-1,0,1]):
  for dr in [-1,0,1]:
   for dc in [-1,0,1]:
    rr,cc=r+dr,c+dc
    if 0<=rr<16 and 0<=cc<27 and B[rr,cc]==3: B[rr,cc]=1
print('\n'.join(' '.join(map(str,row)) for row in B.tolist()))

# label components and identify 2s whose coordinate falls in component bbox; convert local 3 neighborhood
from scipy.ndimage import label
lab,n=label(A==3)
B=A.copy()
for i in range(1,n+1):
 p=np.argwhere(lab==i); lo=p.min(0); hi=p.max(0)
 for r,c in np.argwhere(A==2):
  if lo[0]<=r<=hi[0] and lo[1]<=c<=hi[1]:
   for rr in range(max(0,r-1),min(16,r+2)):
    for cc in range(max(0,c-1),min(27,c+2)):
     if B[rr,cc]==3:B[rr,cc]=1
print('\n'.join(' '.join(map(str,row)) for row in B.tolist()))

